(()=>{'use strict';const $=id=>document.getElementById(id),names={spring:'春 · 桃花池',summer:'夏 · 原清池',autumn:'秋 · 桂影'},scene=location.pathname.split('/')[2];$('map-title').textContent='已选方案 · 春夏13 / 秋14';$('map-cards').replaceChildren();for(const [key,title] of Object.entries(names)){const b=document.createElement('button');b.className='map-card';b.textContent=title;b.setAttribute('aria-pressed',String(scene===key));b.onclick=()=>location.href='../'+key+'/';$('map-cards').append(b);}function update(){$('map-open').textContent=(names[scene]||names.autumn)+' ▾';$('map-save').textContent=location.port==='8814'?'池底细节打磨 · 旧版保留':'已选方案基线 · 不改原文件';}addEventListener('qingchi-scene-ready',update);update();$('season').replaceChildren(new Option(names[scene],scene));$('season').disabled=true;})();